/* Lecture 13 Autonomic Pharmacology: 80 user-supplied MCQs.
 * Preserve question wording, options and supplied keys; append to Exam 2 practice, not flip recall.
 * Clinical review flags mark concepts to independently verify. */
(function(){'use strict';const bank=[{"id":"pharm-e2-user-autonomic13-mcq-001","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #1","q":"Which group of tissues is primarily controlled by the autonomic nervous system (ANS)?","options":["Skeletal muscle and bones","Secretory glands, smooth muscle, cardiac muscle, and visceral organs","Cerebral cortex and spinal cord exclusively","Tendons, ligaments, and cartilage"],"answer":1,"why":"Uploaded answer key: Secretory glands, smooth muscle, cardiac muscle, and visceral organs","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":1},{"id":"pharm-e2-user-autonomic13-mcq-002","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #2","q":"Which statement best distinguishes the sympathetic nervous system (SNS) from the parasympathetic nervous system (PNS)?","options":["The SNS controls voluntary movement, whereas the PNS controls sensation.","Both systems exclusively stimulate organ activity.","The SNS only innervates the heart, while the PNS only innervates the gastrointestinal tract.","The SNS produces fight-or-flight responses, whereas the PNS supports resting physiologic functions."],"answer":3,"why":"Uploaded answer key: The SNS produces fight-or-flight responses, whereas the PNS supports resting physiologic functions.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":2},{"id":"pharm-e2-user-autonomic13-mcq-003","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #3","q":"What is the primary function of a preganglionic autonomic nerve fiber?","options":["Carry impulses from the CNS to an autonomic ganglion","Carry impulses directly from skeletal muscle to the CNS","Release hormones into the bloodstream","Connect the effector organ to the spinal cord without synapsing"],"answer":0,"why":"Uploaded answer key: Carry impulses from the CNS to an autonomic ganglion","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":3},{"id":"pharm-e2-user-autonomic13-mcq-004","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #4","q":"What is the function of a postganglionic autonomic nerve fiber?","options":["Connect two regions of the cerebral cortex","Carry sensory information from skin receptors","Transmit signals from an autonomic ganglion to an effector organ","Directly activate skeletal muscle at the neuromuscular junction"],"answer":2,"why":"Uploaded answer key: Transmit signals from an autonomic ganglion to an effector organ","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":4},{"id":"pharm-e2-user-autonomic13-mcq-005","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #5","q":"Which neurotransmitter is released by preganglionic neurons in both the SNS and PNS?","options":["Norepinephrine","Acetylcholine","Epinephrine","Nitric oxide"],"answer":1,"why":"Uploaded answer key: Acetylcholine","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":5},{"id":"pharm-e2-user-autonomic13-mcq-006","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #6","q":"Which neurotransmitter combination is characteristic of the typical parasympathetic pathway?","options":["Norepinephrine → norepinephrine","Acetylcholine → norepinephrine","Epinephrine → acetylcholine","Acetylcholine → acetylcholine"],"answer":3,"why":"Uploaded answer key: Acetylcholine → acetylcholine","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":6},{"id":"pharm-e2-user-autonomic13-mcq-007","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #7","q":"Which neurotransmitter combination is characteristic of the typical sympathetic pathway?","options":["Acetylcholine → norepinephrine","Acetylcholine → acetylcholine","Norepinephrine → acetylcholine","Nitric oxide → epinephrine"],"answer":0,"why":"Uploaded answer key: Acetylcholine → norepinephrine","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":7},{"id":"pharm-e2-user-autonomic13-mcq-008","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #8","q":"What does the abbreviation NANC represent?","options":["Nicotinic adrenergic neuronal communication","Nonactivated autonomic nerve complex","Non-adrenergic, non-cholinergic neurotransmission","Neuroactive acetylcholine-norepinephrine coupling"],"answer":2,"why":"Uploaded answer key: Non-adrenergic, non-cholinergic neurotransmission","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":8},{"id":"pharm-e2-user-autonomic13-mcq-009","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #9","q":"Which neurotransmitter is identified as the postganglionic mediator of the NANC pathway?","options":["Acetylcholine","Nitric oxide","Epinephrine","Dopamine"],"answer":1,"why":"Nitric oxide activates soluble guanylate cyclase, increasing cGMP in smooth muscle and promoting relaxation. NANC transmitters vary by organ; NO is a prominent inhibitory example.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":9,"originalImportedWhy":"Uploaded answer key: Nitric oxide","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-010","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #10","q":"What makes sympathetic innervation of the adrenal medulla unique in the lecture?","options":["It uses norepinephrine at both synapses.","It contains two postganglionic neurons.","It directly stimulates skeletal muscle.","Preganglionic acetylcholine activates chromaffin cells without a separate postganglionic ganglion."],"answer":3,"why":"Preganglionic sympathetic cholinergic fibers synapse directly on adrenal chromaffin cells, which function like modified postganglionic neurons and release catecholamines into blood.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":10,"originalImportedWhy":"Uploaded answer key: Preganglionic acetylcholine activates chromaffin cells without a separate postganglionic ganglion.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-011","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #11","q":"Activation of adrenal medullary chromaffin cells results in the release of which substances?","options":["Epinephrine and norepinephrine","Acetylcholine and nitric oxide","Insulin and glucagon","Dopamine and serotonin exclusively"],"answer":0,"why":"Uploaded answer key: Epinephrine and norepinephrine","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":11},{"id":"pharm-e2-user-autonomic13-mcq-012","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #12","q":"Which statement best explains why sympathetic and parasympathetic systems often produce opposing physiologic effects?","options":["They always release the same neurotransmitter at their target organs.","They use identical receptors on all tissues.","They activate different receptor pathways that produce contrasting organ responses.","They cannot innervate the same organ."],"answer":2,"why":"The response depends on receptor subtype and tissue distribution rather than the neurotransmitter's name alone; sympathetic and parasympathetic inputs can oppose or complement each other.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":12,"originalImportedWhy":"Uploaded answer key: They activate different receptor pathways that produce contrasting organ responses.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-013","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #13","q":"A frightened horse develops tachycardia, bronchodilation, and decreased gastrointestinal activity. Which autonomic division is primarily responsible?","options":["Parasympathetic","Sympathetic","Somatic sensory","Enteric exclusively"],"answer":1,"why":"Sympathetic activation increases cardiac beta-1 stimulation, circulating catecholamines activate airway beta-2 receptors, and adrenergic effects reduce gastrointestinal activity. An anxious horse may also show physiologic sympathetic arousal, so identify receptors rather than memorizing only 'fight or flight'.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":13,"originalImportedQuestion":"A frightened horse develops tachycardia, bronchodilation, and decreased gastrointestinal activity. Which autonomic division is primarily responsible?","originalImportedAnswer":"Sympathetic","originalImportedWhy":"Uploaded answer key: Sympathetic"},{"id":"pharm-e2-user-autonomic13-mcq-014","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #14","q":"Which response would be expected during increased parasympathetic activity?","options":["Mydriasis and urinary retention","Bronchodilation and tachycardia","Decreased gastrointestinal secretions","Increased gastrointestinal motility and urination"],"answer":3,"why":"Uploaded answer key: Increased gastrointestinal motility and urination","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":14},{"id":"pharm-e2-user-autonomic13-mcq-015","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #15","q":"A drug inhibits the release of norepinephrine from typical sympathetic postganglionic neurons. Which effect is most likely?","options":["Reduced sympathetic stimulation of target tissues","Increased activation of alpha-1 receptors","Increased sympathetic-mediated sphincter contraction","Increased sympathetic-mediated mydriasis"],"answer":0,"why":"Blocking release of norepinephrine reduces adrenergic stimulation of the relevant target. Effects depend on which receptor dominates: alpha-1 constriction and beta-1 cardiac activation are examples.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":15,"originalImportedWhy":"Uploaded answer key: Reduced sympathetic stimulation of target tissues","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-016","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #16","q":"Which receptor type is found at autonomic ganglia in both the SNS and PNS?","options":["Muscarinic receptor","Beta-2 receptor","Nicotinic acetylcholine receptor","Alpha-1 receptor"],"answer":2,"why":"Uploaded answer key: Nicotinic acetylcholine receptor","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":16},{"id":"pharm-e2-user-autonomic13-mcq-017","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #17","q":"Which statement correctly distinguishes nicotinic and muscarinic cholinergic receptors?","options":["Both are G-protein-coupled receptors.","Nicotinic receptors are ion channels, while muscarinic receptors are GPCRs.","Muscarinic receptors are exclusively located at the neuromuscular junction.","Nicotinic receptors only respond to norepinephrine."],"answer":1,"why":"Nicotinic ACh receptors are ligand-gated cation channels that rapidly depolarize neurons or skeletal muscle; muscarinic ACh receptors are G-protein-coupled, producing slower organ-specific signals.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":17,"originalImportedQuestion":"Which statement correctly distinguishes nicotinic and muscarinic cholinergic receptors?","originalImportedAnswer":"Nicotinic receptors are ion channels, while muscarinic receptors are GPCRs.","originalImportedWhy":"Uploaded answer key: Nicotinic receptors are ion channels, while muscarinic receptors are GPCRs."},{"id":"pharm-e2-user-autonomic13-mcq-018","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #18","q":"Which group contains all five adrenergic receptor subtypes identified in the lecture?","options":["M1, M2, M3, M4, M5","Alpha-1, alpha-3, beta-1, beta-4, beta-5","Nicotinic, muscarinic, alpha-1, alpha-2, beta-1","Alpha-1, alpha-2, beta-1, beta-2, beta-3"],"answer":3,"why":"Uploaded answer key: Alpha-1, alpha-2, beta-1, beta-2, beta-3","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":18},{"id":"pharm-e2-user-autonomic13-mcq-019","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #19","q":"Which receptor is primarily responsible for sympathetic-mediated vasoconstriction?","options":["Alpha-1","Beta-2","Beta-3","Muscarinic"],"answer":0,"why":"Uploaded answer key: Alpha-1","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":19},{"id":"pharm-e2-user-autonomic13-mcq-020","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #20","q":"Which adrenergic receptor is associated with increased heart rate?","options":["Beta-3","Alpha-1","Beta-1","Muscarinic"],"answer":2,"why":"Uploaded answer key: Beta-1","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":20},{"id":"pharm-e2-user-autonomic13-mcq-021","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #21","q":"Which receptor is primarily responsible for sympathetic-mediated bronchodilation?","options":["Alpha-1","Beta-2","Muscarinic","Nicotinic"],"answer":1,"why":"Uploaded answer key: Beta-2","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":21},{"id":"pharm-e2-user-autonomic13-mcq-022","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #22","q":"Which receptor is associated with lipolysis?","options":["Alpha-1","Muscarinic","Nicotinic","Beta-3"],"answer":3,"why":"Uploaded answer key: Beta-3","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":22},{"id":"pharm-e2-user-autonomic13-mcq-023","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #23","q":"A drug activates alpha-1 receptors in the urinary tract. Which response is expected?","options":["Increased bladder sphincter contraction and urinary retention","Increased detrusor contraction and urination","Relaxation of the bladder sphincter","Increased parasympathetic stimulation"],"answer":0,"why":"Alpha-1 receptor activation contracts smooth muscle in the bladder outlet and proximal urethra, increasing resistance to urine outflow. It may help sphincter incompetence but worsen retention with obstruction.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":23,"originalImportedWhy":"Uploaded answer key: Increased bladder sphincter contraction and urinary retention","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-024","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #24","q":"Which receptor activation is associated with mydriasis?","options":["Muscarinic","Beta-3","Alpha-1","Nicotinic"],"answer":2,"why":"Uploaded answer key: Alpha-1","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":24},{"id":"pharm-e2-user-autonomic13-mcq-025","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #25","q":"Which physiologic response is associated with muscarinic receptor activation in the eye?","options":["Mydriasis","Miosis","Increased sympathetic tone","Iris dilator muscle contraction"],"answer":1,"why":"Uploaded answer key: Miosis","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":25},{"id":"pharm-e2-user-autonomic13-mcq-026","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #26","q":"Which combination best describes parasympathetic effects on the gastrointestinal tract?","options":["Decreased motility, increased sphincter tone, and decreased secretions","Decreased motility and decreased secretions","Increased sphincter contraction and decreased peristalsis","Increased motility, relaxation of sphincters, and increased secretion"],"answer":3,"why":"Parasympathetic muscarinic activation increases intestinal smooth muscle contraction and secretion while facilitating some sphincter relaxation. Antimuscarinics tend to impair motility.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":26,"originalImportedWhy":"Uploaded answer key: Increased motility, relaxation of sphincters, and increased secretion","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-027","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #27","q":"Which combination best describes sympathetic effects on the urinary bladder?","options":["Reduced bladder muscle contraction and increased sphincter tone","Increased bladder contraction and sphincter relaxation","Increased urination","Increased parasympathetic activity"],"answer":0,"why":"During bladder filling, sympathetic beta signaling relaxes detrusor while alpha-1 signaling increases urethral outlet tone. Voiding reverses this balance.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":27,"originalImportedWhy":"Uploaded answer key: Reduced bladder muscle contraction and increased sphincter tone","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-028","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #28","q":"A patient receives a muscarinic receptor antagonist. Which combination of effects would be expected?","options":["Bradycardia, increased GI motility, and miosis","Increased urination and bronchoconstriction","Mydriasis, reduced GI motility, and urinary retention","Increased salivation and increased bladder contraction"],"answer":2,"why":"Blocking muscarinic receptors relaxes detrusor and iris sphincter and reduces GI activity, explaining urine retention, mydriasis and constipation/ileus concerns.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":28,"originalImportedWhy":"Uploaded answer key: Mydriasis, reduced GI motility, and urinary retention","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-029","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #29","q":"Which autonomic response is most useful for increasing oxygen intake during an emergency?","options":["Alpha-1-mediated vasoconstriction","Beta-2-mediated bronchodilation","Beta-3-mediated lipolysis","Muscarinic-mediated bronchoconstriction"],"answer":1,"why":"Beta-2 activation increases cAMP in airway smooth muscle and promotes relaxation. In a patient with breathing difficulty, bronchodilation helps only when reversible bronchospasm is part of the problem.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":29,"originalImportedWhy":"Uploaded answer key: Beta-2-mediated bronchodilation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-030","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #30","q":"Which combination of autonomic changes would most strongly indicate sympathetic activation?","options":["Bradycardia, miosis, and urination","Increased intestinal motility and salivation","Bronchoconstriction and increased GI secretions","Tachycardia, mydriasis, bronchodilation, and urinary retention"],"answer":3,"why":"Uploaded answer key: Tachycardia, mydriasis, bronchodilation, and urinary retention","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":30},{"id":"pharm-e2-user-autonomic13-mcq-031","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #31","q":"Which combination of autonomic actions promotes urinary retention?","options":["SNS activation or PNS inhibition","SNS inhibition or PNS activation","Muscarinic activation and alpha-1 inhibition","Reduced sphincter tone and increased detrusor contraction"],"answer":0,"why":"Storage of urine requires a relaxed detrusor and adequately contracted urethral outlet. Sympathetic activation favors this state via beta and alpha-1 receptors.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":31,"originalImportedWhy":"Uploaded answer key: SNS activation or PNS inhibition","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-032","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #32","q":"Which combination promotes urination?","options":["SNS activation and PNS inhibition","Alpha-1 activation and muscarinic inhibition","PNS activation or SNS inhibition","Increased sphincter contraction"],"answer":2,"why":"Voiding requires detrusor contraction through muscarinic receptors and reduced outflow resistance via less alpha-1-mediated tone.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":32,"originalImportedWhy":"Uploaded answer key: PNS activation or SNS inhibition","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-033","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #33","q":"In a dog with urethral sphincter mechanism incompetence and urinary leakage, why is phenylpropanolamine used?","options":["It increases urethral closure pressure by stimulating alpha-adrenergic smooth-muscle contraction.","It relaxes an obstructed urethra by blocking alpha-1 receptors.","It directly strengthens detrusor contraction to empty the bladder.","It reduces urine formation by inhibiting renal filtration."],"answer":0,"why":"Phenylpropanolamine increases alpha-adrenergic tone at the urethral sphincter, improving storage-phase closure pressure and reducing leakage. It is used for urethral sphincter mechanism incompetence, not arbitrary inappropriate urination caused by behavioral or inflammatory disease.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":33,"originalImportedQuestion":"What is the primary therapeutic purpose of phenylpropanolamine (P3)?","originalImportedAnswer":"Promote urinary retention in patients with inappropriate urination","originalImportedWhy":"Uploaded answer key: Promote urinary retention in patients with inappropriate urination","reviewFlag":"Corrected vague and misleading original answer 'inappropriate urination' to proper indication and outlet mechanism."},{"id":"pharm-e2-user-autonomic13-mcq-034","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #34","q":"Which mechanism best explains phenylpropanolamine's benefit in canine urethral sphincter mechanism incompetence?","options":["Muscarinic activation of detrusor contraction","Beta-2-mediated detrusor relaxation alone","Nicotinic neuromuscular blockade","Alpha-adrenergic stimulation of urethral sphincter smooth muscle"],"answer":3,"why":"Alpha-adrenergic agonism increases urethral closure pressure; indirect norepinephrine release also contributes to sympathomimetic effects. Cardiovascular adverse effects can occur, but beta-1 stimulation is not the primary therapeutic target.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":34,"originalImportedQuestion":"Which receptors are activated by phenylpropanolamine according to the lecture?","originalImportedAnswer":"Alpha-1 and beta-1 receptors","originalImportedWhy":"Uploaded answer key: Alpha-1 and beta-1 receptors"},{"id":"pharm-e2-user-autonomic13-mcq-035","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #35","q":"Why can phenylpropanolamine produce cardiovascular adverse effects?","options":["Its adrenergic activity is not restricted to the urinary tract.","It exclusively activates bladder muscarinic receptors.","It irreversibly inhibits acetylcholinesterase.","It blocks all sympathetic activity."],"answer":0,"why":"Phenylpropanolamine has systemic sympathomimetic activity as well as effects on urethral closure. Hypertension, tachycardia and agitation are potential reasons to evaluate cardiovascular history.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":35,"originalImportedWhy":"Uploaded answer key: Its adrenergic activity is not restricted to the urinary tract.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-036","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #36","q":"What is the mechanism of action of oxybutynin?","options":["Alpha-1 receptor agonism","Beta-1 receptor antagonism","Muscarinic receptor antagonism","Nicotinic receptor activation"],"answer":2,"why":"Uploaded answer key: Muscarinic receptor antagonism","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":36},{"id":"pharm-e2-user-autonomic13-mcq-037","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #37","q":"How does oxybutynin compare with phenylpropanolamine regarding adverse effects?","options":["Oxybutynin produces more cardiovascular effects and fewer gastrointestinal effects.","Oxybutynin generally produces fewer cardiovascular effects but more gastrointestinal effects.","Both have identical receptor activity.","Neither drug affects gastrointestinal function."],"answer":1,"why":"Oxybutynin reduces parasympathetic bladder contraction; its adverse effects include dry mouth, constipation and retention. Phenylpropanolamine primarily raises outlet tone and can produce cardiovascular effects.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":37,"originalImportedWhy":"Uploaded answer key: Oxybutynin generally produces fewer cardiovascular effects but more gastrointestinal effects.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-038","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #38","q":"Which patient would be most appropriate for oxybutynin according to the lecture's pharmacologic principles?","options":["A cat with urethral obstruction requiring sphincter relaxation","A dog with poor detrusor contraction requiring stimulation","A horse with severe urinary retention","A dog with inappropriate urination associated with excessive bladder contraction"],"answer":3,"why":"Uploaded answer key: A dog with inappropriate urination associated with excessive bladder contraction","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":38},{"id":"pharm-e2-user-autonomic13-mcq-039","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #39","q":"What is the primary mechanism of action of prazosin?","options":["Alpha-1 receptor antagonism","Alpha-1 receptor agonism","Muscarinic receptor activation","Beta-2 receptor activation"],"answer":0,"why":"Prazosin competitively antagonizes alpha-1 adrenergic receptors, relaxing urethral smooth muscle and reducing outlet resistance. Check for obstruction and hemodynamic effects; it does not directly cause detrusor contraction.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":39,"originalImportedQuestion":"What is the primary mechanism of action of prazosin?","originalImportedAnswer":"Alpha-1 receptor antagonism","originalImportedWhy":"Uploaded answer key: Alpha-1 receptor antagonism"},{"id":"pharm-e2-user-autonomic13-mcq-040","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #40","q":"Why can prazosin promote urination?","options":["It stimulates bladder muscarinic receptors.","It increases detrusor contraction through beta-1 receptors.","It reduces alpha-1-mediated urethral sphincter tone.","It directly stimulates acetylcholine release."],"answer":2,"why":"Alpha-1 blockade relaxes urethral smooth muscle, lowering outlet resistance. It cannot dissolve a urethral obstruction and may cause systemic hypotension.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":40,"originalImportedWhy":"Uploaded answer key: It reduces alpha-1-mediated urethral sphincter tone.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-041","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #41","q":"Which drug is described as a selective alpha-1 antagonist particularly useful for urethrospasm associated with urethritis or urethroliths?","options":["Phenylpropanolamine","Tamsulosin","Oxybutynin","Bethanechol"],"answer":1,"why":"Uploaded answer key: Tamsulosin","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":41,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved."},{"id":"pharm-e2-user-autonomic13-mcq-042","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #42","q":"How do prazosin and tamsulosin differ?","options":["Tamsulosin activates muscarinic receptors.","Prazosin blocks both alpha-1 and alpha-2 receptors equally.","Tamsulosin irreversibly blocks alpha-1 receptors.","Both block alpha-1 receptors; tamsulosin is relatively more selective for alpha-1A/alpha-1D subtypes in the lower urinary tract."],"answer":3,"why":"Prazosin is itself a selective alpha-1 blocker (versus alpha-2), while tamsulosin is relatively selective for urinary-tract alpha-1 subtypes. The original wording incorrectly described prazosin as nonselective.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":42,"reviewFlag":"Corrected alpha-1-selectivity error in original uploaded key.","originalImportedQuestion":"What distinguishes tamsulosin from prazosin in the lecture?","originalImportedAnswer":"Tamsulosin is described as a selective alpha-1 antagonist, whereas prazosin is described as nonselective.","originalImportedWhy":"Uploaded answer key: Tamsulosin is described as a selective alpha-1 antagonist, whereas prazosin is described as nonselective."},{"id":"pharm-e2-user-autonomic13-mcq-043","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #43","q":"Which drug causes long-lasting irreversible alpha-adrenergic receptor blockade?","options":["Phenoxybenzamine","Prazosin","Tamsulosin","Phenylpropanolamine"],"answer":0,"why":"Phenoxybenzamine forms an irreversible, nonselective alpha-adrenergic blockade affecting alpha-1 and alpha-2 receptors. Prazosin and tamsulosin act reversibly at alpha-1 receptors.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":43,"originalImportedQuestion":"Which medication irreversibly antagonizes alpha-1 receptors?","originalImportedAnswer":"Phenoxybenzamine","originalImportedWhy":"Uploaded answer key: Phenoxybenzamine"},{"id":"pharm-e2-user-autonomic13-mcq-044","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #44","q":"What is the primary therapeutic indication for phenoxybenzamine in the lecture?","options":["Urinary incontinence","Ophthalmic dilation","Pheochromocytoma-associated hypertension","Feline urethrospasm exclusively"],"answer":2,"why":"Uploaded answer key: Pheochromocytoma-associated hypertension","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":44},{"id":"pharm-e2-user-autonomic13-mcq-045","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #45","q":"Why may phenoxybenzamine promote urination even when prescribed for another condition?","options":["It stimulates detrusor muscarinic receptors.","Alpha-1 blockade reduces urethral sphincter tone.","It increases norepinephrine release.","It activates sympathetic pathways."],"answer":1,"why":"Irreversible/nonselective alpha blockade can relax urinary-outlet smooth muscle even when the main indication is catecholamine-mediated hypertension. Orthostatic hypotension is a consideration.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":45,"originalImportedWhy":"Uploaded answer key: Alpha-1 blockade reduces urethral sphincter tone.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-046","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #46","q":"Which drug is a muscarinic receptor agonist used to promote urination?","options":["Oxybutynin","Prazosin","Phenylpropanolamine","Bethanechol"],"answer":3,"why":"Uploaded answer key: Bethanechol","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":46},{"id":"pharm-e2-user-autonomic13-mcq-047","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #47","q":"How does bethanechol promote urination?","options":["By stimulating bladder smooth muscle contraction through muscarinic receptors","By blocking bladder muscarinic receptors","By increasing alpha-1-mediated sphincter tone","By stimulating beta-1 receptors"],"answer":0,"why":"Bethanechol activates muscarinic receptors on detrusor muscle to increase contraction. It will not overcome a mechanical urethral obstruction, which must be excluded.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":47,"originalImportedWhy":"Uploaded answer key: By stimulating bladder smooth muscle contraction through muscarinic receptors","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-048","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #48","q":"Which situation makes bethanechol unsafe or inappropriate for promoting bladder emptying?","options":["A weak urethral sphincter without outflow obstruction","A patient with normal bladder wall integrity","Suspected mechanical urethral obstruction or compromised bladder wall integrity","A patient with reduced sympathetic stimulation"],"answer":2,"why":"Bethanechol stimulates muscarinic receptors to increase detrusor contraction. Contracting against a blocked outlet increases pressure and can worsen injury or cause bladder rupture; ensure the urethra is patent before using it.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":48,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved.","originalImportedQuestion":"According to the lecture, when is bethanechol contraindicated?","originalImportedAnswer":"When bladder wall integrity is compromised or dysfunction follows previous urethral obstruction","originalImportedWhy":"Uploaded answer key: When bladder wall integrity is compromised or dysfunction follows previous urethral obstruction"},{"id":"pharm-e2-user-autonomic13-mcq-049","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #49","q":"A cat has excessive urethral sphincter tone associated with urethritis. Which drug would best address the mechanism described in the lecture?","options":["Phenylpropanolamine","Tamsulosin","Oxybutynin","Atropine"],"answer":1,"why":"Uploaded answer key: Tamsulosin","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":49},{"id":"pharm-e2-user-autonomic13-mcq-050","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #50","q":"Which drug-mechanism pairing is correct?","options":["Phenylpropanolamine — muscarinic antagonist","Oxybutynin — alpha-1 agonist","Bethanechol — alpha-1 antagonist","Prazosin — alpha-1 antagonist"],"answer":3,"why":"Uploaded answer key: Prazosin — alpha-1 antagonist","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":50},{"id":"pharm-e2-user-autonomic13-mcq-051","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #51","q":"Which autonomic changes promote mydriasis?","options":["SNS activation or PNS inhibition","SNS inhibition or PNS activation","Muscarinic activation exclusively","Increased iris constrictor muscle activity"],"answer":0,"why":"Uploaded answer key: SNS activation or PNS inhibition","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":51},{"id":"pharm-e2-user-autonomic13-mcq-052","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #52","q":"Which autonomic changes promote miosis?","options":["Alpha-1 activation","Muscarinic inhibition","PNS activation or SNS inhibition","Increased sympathetic activity"],"answer":2,"why":"Uploaded answer key: PNS activation or SNS inhibition","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":52},{"id":"pharm-e2-user-autonomic13-mcq-053","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #53","q":"What is the mechanism of action of tropicamide?","options":["Alpha-1 receptor agonism","Muscarinic receptor antagonism","Beta-2 receptor activation","Nicotinic receptor antagonism"],"answer":1,"why":"Uploaded answer key: Muscarinic receptor antagonism","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":53},{"id":"pharm-e2-user-autonomic13-mcq-054","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #54","q":"Why is tropicamide commonly selected for ophthalmic examinations?","options":["It produces permanent dilation.","It stimulates aqueous humor production.","It causes long-term paralysis of the iris.","It is a relatively short-acting mydriatic."],"answer":3,"why":"Tropicamide is a short-acting muscarinic antagonist; it relaxes iris sphincter and dilates the pupil without the much longer cycloplegic effect of atropine.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":54,"originalImportedWhy":"Uploaded answer key: It is a relatively short-acting mydriatic.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-055","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #55","q":"How does iris pigmentation influence the effects of tropicamide?","options":["More pigmented irises generally exhibit slower onset and longer duration.","More pigmented irises always dilate faster.","Iris pigmentation has no influence on drug activity.","Blue irises always have longer drug duration than brown irises."],"answer":0,"why":"Uploaded answer key: More pigmented irises generally exhibit slower onset and longer duration.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":55},{"id":"pharm-e2-user-autonomic13-mcq-056","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #56","q":"Why may tropicamide produce a longer duration of action in an animal with a dark brown iris?","options":["Melanin permanently destroys tropicamide.","Melanin increases systemic drug clearance.","Melanin binds the drug and allows prolonged release.","Dark irises contain no muscarinic receptors."],"answer":2,"why":"Pigment binding can delay effective free drug concentrations and prolong release, changing ophthalmic onset/duration in some patients.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":56,"originalImportedWhy":"Uploaded answer key: Melanin binds the drug and allows prolonged release.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-057","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #57","q":"Which drug is a long-acting muscarinic antagonist used in the management of uveitis?","options":["Pilocarpine","Atropine","Demecarium bromide","Phenylephrine"],"answer":1,"why":"Uploaded answer key: Atropine","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":57},{"id":"pharm-e2-user-autonomic13-mcq-058","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #58","q":"Why is atropine useful in patients with uveitis?","options":["It stimulates iris sphincter contraction.","It increases parasympathetic activity.","It directly eliminates all intraocular inflammation.","It improves ocular comfort and reduces the risk of posterior synechiae."],"answer":3,"why":"Atropine blocks muscarinic receptors in the iris sphincter and ciliary body, producing mydriasis and cycloplegia. In anterior uveitis this decreases painful ciliary spasm and helps prevent posterior synechiae; avoid when contraindicated (e.g., glaucoma).","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":58,"originalImportedQuestion":"Why is atropine useful in patients with uveitis?","originalImportedAnswer":"It improves ocular comfort and reduces the risk of posterior synechiae.","originalImportedWhy":"Uploaded answer key: It improves ocular comfort and reduces the risk of posterior synechiae."},{"id":"pharm-e2-user-autonomic13-mcq-059","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #59","q":"Which complication is associated with ophthalmic atropine use in horses?","options":["Colic due to prolonged antimuscarinic effects","Severe hypoglycemia","Permanent adrenal suppression","Excessive insulin release"],"answer":0,"why":"Ophthalmic atropine may be absorbed systemically; antimuscarinic effects can decrease gut motility and precipitate colic in susceptible horses.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":59,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved.","originalImportedWhy":"Uploaded answer key: Colic due to prolonged antimuscarinic effects","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-060","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #60","q":"Why does the lecture recommend atropine ointment rather than drops in cats?","options":["Ointment permanently blocks all muscarinic receptors.","Drops cannot penetrate the cornea.","Drops may cause hypersalivation.","Ointment produces miosis."],"answer":2,"why":"Uploaded answer key: Drops may cause hypersalivation.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":60},{"id":"pharm-e2-user-autonomic13-mcq-061","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #61","q":"Which conditions are identified as contraindications for atropine?","options":["Uveitis and posterior synechiae","Glaucoma and keratoconjunctivitis sicca (KCS)","Mydriasis and iris pigmentation","Corneal pigmentation and cataracts exclusively"],"answer":1,"why":"Uploaded answer key: Glaucoma and keratoconjunctivitis sicca (KCS)","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":61},{"id":"pharm-e2-user-autonomic13-mcq-062","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #62","q":"From which plant is atropine derived?","options":["Digitalis purpurea","Taxus baccata","Nerium oleander","Atropa belladonna"],"answer":3,"why":"Uploaded answer key: Atropa belladonna","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":62},{"id":"pharm-e2-user-autonomic13-mcq-063","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #63","q":"What is the mechanism of action of phenylephrine when used as an ophthalmic mydriatic?","options":["Alpha-1 receptor agonism","Muscarinic receptor agonism","Beta-3 receptor antagonism","Acetylcholinesterase inhibition"],"answer":0,"why":"Uploaded answer key: Alpha-1 receptor agonism","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":63},{"id":"pharm-e2-user-autonomic13-mcq-064","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #64","q":"Why might phenylephrine be combined with tropicamide or atropine?","options":["To produce miosis","To inhibit sympathetic activation","To promote mydriasis through complementary autonomic mechanisms","To prevent alpha-1 receptor activation"],"answer":2,"why":"Phenylephrine contracts the radial iris dilator muscle through alpha-1 receptors; tropicamide or atropine blocks the muscarinic iris sphincter. The complementary actions produce mydriasis.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":64,"originalImportedWhy":"Uploaded answer key: To promote mydriasis through complementary autonomic mechanisms","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-065","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #65","q":"Which medications are identified as miotic agents in the lecture?","options":["Tropicamide and atropine","Pilocarpine and demecarium bromide","Phenylephrine and phenylpropanolamine","Prazosin and tamsulosin"],"answer":1,"why":"Uploaded answer key: Pilocarpine and demecarium bromide","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":65,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved."},{"id":"pharm-e2-user-autonomic13-mcq-066","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #66","q":"Which patient is most appropriate for a miotic drug such as pilocarpine after an ophthalmic examination?","options":["A patient requiring pharmacologic dilation for a fundic examination.","A patient with anterior lens luxation and uncontrolled elevated IOP; treat empirically without assessing the lens.","A patient with a selected form of glaucoma for which improving trabecular aqueous outflow is appropriate, with the lens position confirmed.","A patient with acute uveitis needing dilation to prevent synechiae."],"answer":2,"why":"Pilocarpine's muscarinic action contracts the iris sphincter and ciliary muscle, producing miosis and potentially improving conventional aqueous outflow in selected cases. Lens instability/luxation and uveitis require specific assessment; the original indication ambiguously included lens instability.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":66,"originalImportedQuestion":"Which condition is identified as an indication for miotic drugs?","originalImportedAnswer":"Glaucoma not secondary to lens luxation, or lens instability","originalImportedWhy":"Uploaded answer key: Glaucoma not secondary to lens luxation, or lens instability","reviewFlag":"Replaced ambiguous miotic indication; lens luxation can make miosis unsafe."},{"id":"pharm-e2-user-autonomic13-mcq-067","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #67","q":"A veterinarian wants to produce miosis rather than mydriasis. Which pharmacologic approach is most appropriate?","options":["Activation of muscarinic receptors","Inhibition of muscarinic receptors","Activation of alpha-1 receptors","Administration of phenylephrine"],"answer":0,"why":"Uploaded answer key: Activation of muscarinic receptors","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":67,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved."},{"id":"pharm-e2-user-autonomic13-mcq-068","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #68","q":"What is the normal function of acetylcholinesterase (AChE)?","options":["Stimulate norepinephrine release","Activate alpha-1 receptors","Break down acetylcholine at cholinergic synapses","Convert acetylcholine into epinephrine"],"answer":2,"why":"Uploaded answer key: Break down acetylcholine at cholinergic synapses","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":68},{"id":"pharm-e2-user-autonomic13-mcq-069","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #69","q":"How do organophosphate insecticides produce toxicity in vertebrates?","options":["By blocking all muscarinic receptors","By inhibiting acetylcholinesterase and causing excessive cholinergic stimulation","By stimulating norepinephrine degradation","By directly activating beta-2 receptors"],"answer":1,"why":"Organophosphates inhibit acetylcholinesterase, allowing ACh accumulation at muscarinic, nicotinic and CNS synapses. Signs include secretions, bronchoconstriction, muscle fasciculations/weakness and possible seizures; respiratory failure is a major risk.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":69,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved.","originalImportedQuestion":"How do organophosphate insecticides produce toxicity in vertebrates?","originalImportedAnswer":"By inhibiting acetylcholinesterase and causing excessive cholinergic stimulation","originalImportedWhy":"Uploaded answer key: By inhibiting acetylcholinesterase and causing excessive cholinergic stimulation"},{"id":"pharm-e2-user-autonomic13-mcq-070","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #70","q":"Which group of clinical signs is represented by the lecture's SLUDD mnemonic?","options":["Seizures, lethargy, urticaria, dehydration, depression","Salivation, lacrimation, urticaria, diarrhea, depression","Sweating, lethargy, urination, dyspnea, diarrhea","Salivation, lacrimation, urination, defecation, dyspnea"],"answer":3,"why":"Uploaded answer key: Salivation, lacrimation, urination, defecation, dyspnea","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":70},{"id":"pharm-e2-user-autonomic13-mcq-071","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #71","q":"Why can organophosphate poisoning produce prolonged clinical signs?","options":["Organophosphates can covalently inhibit acetylcholinesterase.","Organophosphates are rapidly eliminated without affecting receptors.","Organophosphates permanently activate beta-1 receptors.","Organophosphates inhibit all neurotransmitter release."],"answer":0,"why":"Organophosphates phosphorylate AChE and the enzyme can undergo aging, making reactivation difficult. Persistent effects can continue until adequate functional enzyme activity returns.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":71,"originalImportedWhy":"Uploaded answer key: Organophosphates can covalently inhibit acetylcholinesterase.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-072","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #72","q":"Which medication is used to antagonize muscarinic effects during organophosphate poisoning?","options":["Bethanechol","Pilocarpine","Atropine","Phenylephrine"],"answer":2,"why":"Uploaded answer key: Atropine","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":72},{"id":"pharm-e2-user-autonomic13-mcq-073","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #73","q":"What is the therapeutic role of pralidoxime (2-PAM) in organophosphate poisoning?","options":["Stimulate acetylcholine synthesis","Reactivate inhibited acetylcholinesterase when administered early enough","Directly block alpha-1 receptors","Produce prolonged muscarinic activation"],"answer":1,"why":"Pralidoxime can remove phosphate from inhibited acetylcholinesterase before enzyme aging makes binding effectively irreversible. Atropine treats muscarinic symptoms but does not reverse nicotinic muscle weakness; early decontamination and supportive ventilation may be essential.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":73,"originalImportedQuestion":"What is the therapeutic role of pralidoxime (2-PAM) in organophosphate poisoning?","originalImportedAnswer":"Reactivate inhibited acetylcholinesterase when administered early enough","originalImportedWhy":"Uploaded answer key: Reactivate inhibited acetylcholinesterase when administered early enough"},{"id":"pharm-e2-user-autonomic13-mcq-074","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #74","q":"According to the lecture, when should pralidoxime ideally be administered?","options":["Only after seven days","Only after all cholinergic signs resolve","At least 72 hours after exposure","Within approximately 24 hours of exposure, in combination with atropine"],"answer":3,"why":"Uploaded answer key: Within approximately 24 hours of exposure, in combination with atropine","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":74,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved."},{"id":"pharm-e2-user-autonomic13-mcq-075","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #75","q":"Why is atropine used with pralidoxime during organophosphate poisoning?","options":["Atropine blocks muscarinic effects while pralidoxime attempts to restore acetylcholinesterase activity.","Atropine directly reactivates acetylcholinesterase.","Pralidoxime permanently activates muscarinic receptors.","Both medications inhibit acetylcholine synthesis."],"answer":0,"why":"Atropine blocks muscarinic secretions, bronchoconstriction and bradycardia, while pralidoxime aims to restore AChE activity. Neither replaces respiratory support or appropriate decontamination.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":75,"reviewFlag":"Clinical or receptor-specific interpretation requires independent verification; original lecture question and key preserved.","originalImportedWhy":"Uploaded answer key: Atropine blocks muscarinic effects while pralidoxime attempts to restore acetylcholinesterase activity.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-076","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #76","q":"Why are drugs targeting nicotinic receptors at autonomic ganglia considered impractical according to the lecture?","options":["Nicotinic receptors are absent from autonomic ganglia.","Nicotinic receptors only exist in the CNS.","Ganglionic stimulation affects both SNS and PNS pathways, producing competing effects.","Nicotinic receptors respond only to norepinephrine."],"answer":2,"why":"Uploaded answer key: Ganglionic stimulation affects both SNS and PNS pathways, producing competing effects.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":76},{"id":"pharm-e2-user-autonomic13-mcq-077","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #77","q":"Which statement best describes the mechanism of succinylcholine?","options":["It competitively blocks muscarinic receptors.","It activates nicotinic acetylcholine receptors at the neuromuscular junction, causing excessive activation and ultimately flaccid paralysis.","It inhibits alpha-1 receptors.","It stimulates beta-2-mediated bronchodilation."],"answer":1,"why":"Succinylcholine is a depolarizing neuromuscular blocker. Sustained nicotinic activation renders voltage-gated sodium channels inexcitable, causing flaccid paralysis after fasciculations.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":77,"originalImportedWhy":"Uploaded answer key: It activates nicotinic acetylcholine receptors at the neuromuscular junction, causing excessive activation and ultimately flaccid paralysis.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-078","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #78","q":"Why does succinylcholine produce flaccid paralysis despite initially activating nicotinic receptors?","options":["It increases norepinephrine release.","It permanently blocks muscarinic receptors.","It directly destroys skeletal muscle fibers.","Persistent depolarization prevents normal neuromuscular transmission."],"answer":3,"why":"Persistent endplate depolarization prevents restoration of normal excitability, so voluntary impulses cannot trigger effective muscle contraction. The patient is paralyzed but not anesthetized or analgesic.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":78,"originalImportedWhy":"Uploaded answer key: Persistent depolarization prevents normal neuromuscular transmission.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-079","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #79","q":"What is the most dangerous consequence of excessive succinylcholine-induced neuromuscular blockade?","options":["Diaphragmatic paralysis and respiratory failure","Increased gastrointestinal motility","Severe mydriasis","Increased urinary sphincter tone"],"answer":0,"why":"Paralysis of respiratory muscles prevents ventilation even if the patient remains conscious. Mechanical ventilation and adequate anesthesia are essential whenever a neuromuscular blocker is used.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":79,"originalImportedWhy":"Uploaded answer key: Diaphragmatic paralysis and respiratory failure","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-autonomic13-mcq-080","lecture":"Lecture 13","sourceGroup":"Lecture 13 · uploaded MCQ set","topic":"Autonomic Pharmacology · #80","q":"A patient receives succinylcholine during anesthesia. Which statement best explains its pharmacologic effect according to the lecture?","options":["It blocks sympathetic alpha-1 receptors and causes urinary retention.","It stimulates muscarinic receptors to produce skeletal muscle contraction.","It activates nicotinic receptors at the neuromuscular junction, ultimately producing flaccid paralysis.","It inhibits acetylcholine synthesis within motor neurons."],"answer":2,"why":"Uploaded answer key: It activates nicotinic receptors at the neuromuscular junction, ultimately producing flaccid paralysis.","source":"User-supplied Lecture 13 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":80}];const target=window.VPQ_PHARM_EXAM2_PDF_PRACTICE||(window.VPQ_PHARM_EXAM2_PDF_PRACTICE=[]);const ids=new Set(target.map(x=>x.id));for(const q of bank){if(!ids.has(q.id)){target.push(q);ids.add(q.id)}}window.VPQ_PHARM_AUTONOMIC13_UPLOADED_MCQ_COUNT=bank.length;})();
